"""Safety check for SQL generated by the studio-cf tools (stdlib only).

The studio's tables live in a D1 database that another project also uses, so every
object the studio touches is prefixed ``vf_``. This module rejects any SQL that could
touch anything else. The tools call it on generated SQL before writing, applying or
printing a command for it.

It is a whitelist, not a blacklist. A statement must be one of:

    CREATE TABLE IF NOT EXISTS vf_x (...)
    CREATE [UNIQUE] INDEX IF NOT EXISTS vf_x ON vf_y (...)
    INSERT [OR REPLACE | OR IGNORE | OR ABORT] INTO vf_x ...
    DELETE FROM vf_x ...
    SELECT ... FROM vf_x ...

and every table named after FROM, JOIN, INTO, TABLE, or the ON of CREATE INDEX must be
an unquoted, unqualified ``vf_`` name. Quoted identifiers, ``schema.table`` names,
``sqlite_*`` and ``_cf_*`` names, comma joins to other tables, and the words DROP, ALTER,
ATTACH, DETACH, PRAGMA, VACUUM, REINDEX, TRIGGER, VIEW and UPDATE (other than the
``DO UPDATE`` of an upsert) are refused. String literals and comments are ignored by
the scan (JSON data may contain anything). Messages never echo string literals.
"""
import re

PREFIX = "vf_"

_WORD = re.compile(r"[A-Za-z_][A-Za-z0-9_$]*")
_NUM = re.compile(r"[0-9][0-9A-Za-z_.]*|\?[0-9]*|[:@$][A-Za-z0-9_]+")

BANNED_WORDS = {"DROP", "ALTER", "ATTACH", "DETACH", "PRAGMA", "VACUUM", "REINDEX", "TRIGGER", "VIEW", "TEMP", "TEMPORARY"}
# words that may follow a table name in a FROM clause without being an alias
_CLAUSE_WORDS = {"WHERE", "ORDER", "GROUP", "HAVING", "LIMIT", "OFFSET", "JOIN", "INNER", "LEFT", "RIGHT", "FULL", "CROSS",
                 "NATURAL", "OUTER", "ON", "USING", "UNION", "INTERSECT", "EXCEPT", "WINDOW", "AS", "INDEXED", "NOT"}


class SqlGuardError(ValueError):
    pass


def tokenize(sql):
    """Returns a list of (kind, text) with kind in WORD STR QID NUM PUNCT. Comments are dropped."""
    toks, i, n = [], 0, len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
        elif sql.startswith("--", i):
            j = sql.find("\n", i)
            i = n if j < 0 else j + 1
        elif sql.startswith("/*", i):
            j = sql.find("*/", i + 2)
            if j < 0:
                raise SqlGuardError("unterminated comment")
            i = j + 2
        elif c == "'":
            j = i + 1
            while True:
                j = sql.find("'", j)
                if j < 0:
                    raise SqlGuardError("unterminated string literal")
                if sql.startswith("''", j):
                    j += 2
                    continue
                break
            toks.append(("STR", ""))
            i = j + 1
        elif c in '"`[':
            toks.append(("QID", c))
            i += 1
            # skip to the closing quote so its contents are not mis-tokenised
            close = {'"': '"', "`": "`", "[": "]"}[c]
            j = sql.find(close, i)
            if j < 0:
                raise SqlGuardError("unterminated quoted identifier")
            i = j + 1
        else:
            m, kind = _WORD.match(sql, i), "WORD"
            if not m:
                m, kind = _NUM.match(sql, i), "NUM"
            if m:
                toks.append((kind, m.group(0)))
                i = m.end()
            else:
                toks.append(("PUNCT", c))
                i += 1
    return toks


def _split(toks):
    stmt, out = [], []
    for t in toks:
        if t == ("PUNCT", ";"):
            if stmt:
                out.append(stmt)
            stmt = []
        else:
            stmt.append(t)
    if stmt:
        out.append(stmt)
    return out


def _name_ok(toks, i):
    """toks[i] must be a bare vf_ table name (not qualified). Returns an error string or None."""
    if i >= len(toks):
        return "missing table name"
    kind, text = toks[i]
    if kind != "WORD":
        return "table name is quoted or not a plain identifier"
    if not text.lower().startswith(PREFIX) or len(text) <= len(PREFIX):
        return f"table or index {text!r} is not a {PREFIX} object"
    if i + 1 < len(toks) and toks[i + 1] == ("PUNCT", "."):
        return f"qualified name after {text!r}"
    if i > 0 and toks[i - 1] == ("PUNCT", "."):
        return f"qualified name {text!r}"
    return None


def _check_statement(toks):
    errs = []
    words = [t[1].upper() if t[0] == "WORD" else None for t in toks]

    def at(k):
        return words[k] if 0 <= k < len(words) else None

    if any(t[0] == "QID" for t in toks):
        errs.append("quoted identifiers are not allowed")

    # statement shape
    if at(0) == "CREATE" and at(1) == "TABLE":
        if (at(2), at(3), at(4)) != ("IF", "NOT", "EXISTS"):
            errs.append("CREATE TABLE must use IF NOT EXISTS")
        shape_name = 5
    elif at(0) == "CREATE" and (at(1) == "INDEX" or (at(1) == "UNIQUE" and at(2) == "INDEX")):
        k = 2 if at(1) == "INDEX" else 3
        if (at(k), at(k + 1), at(k + 2)) != ("IF", "NOT", "EXISTS"):
            errs.append("CREATE INDEX must use IF NOT EXISTS")
        e = _name_ok(toks, k + 3)
        if e:
            errs.append(e)
        shape_name = None
        try:
            on = words.index("ON", k + 3)
        except ValueError:
            on = None
            errs.append("CREATE INDEX without ON")
        if on is not None:
            e = _name_ok(toks, on + 1)
            if e:
                errs.append(e)
    elif at(0) == "INSERT":
        k = 1
        if at(1) == "OR":
            if at(2) not in ("REPLACE", "IGNORE", "ABORT"):
                errs.append("unsupported INSERT OR clause")
            k = 3
        if at(k) != "INTO":
            errs.append("INSERT without INTO")
        shape_name = None  # the INTO target is checked by the reference scan below
    elif at(0) == "DELETE" and at(1) == "FROM":
        shape_name = None  # the FROM target is checked by the reference scan below
    elif at(0) == "SELECT":
        shape_name = None
    else:
        return [f"statement type {(at(0) or toks[0][1])!r} is not allowed"]
    if shape_name is not None:  # CREATE TABLE
        e = _name_ok(toks, shape_name)
        if e:
            errs.append(e)

    # every table reference anywhere in the statement (subselects included)
    for i, w in enumerate(words):
        if w is None:
            continue
        if w in BANNED_WORDS:
            errs.append(f"{w} is not allowed")
        if w == "UPDATE" and at(i - 1) != "DO":
            errs.append("UPDATE is not allowed")
        if w in ("FROM", "JOIN"):
            j = i + 1
            if j < len(toks) and toks[j] == ("PUNCT", "("):
                continue  # subselect; its own FROM is checked on its own turn
            while True:
                e = _name_ok(toks, j)
                if e:
                    errs.append(e)
                    break
                j += 1
                # optional alias
                if j < len(toks) and toks[j][0] == "WORD" and toks[j][1].upper() == "AS":
                    j += 2
                elif j < len(toks) and toks[j][0] == "WORD" and toks[j][1].upper() not in _CLAUSE_WORDS:
                    j += 1
                if j < len(toks) and toks[j] == ("PUNCT", ","):
                    j += 1
                    continue
                break
        if w == "INTO":
            e = _name_ok(toks, i + 1)
            if e:
                errs.append(e)
        if w in ("SQLITE_MASTER", "SQLITE_SCHEMA", "SQLITE_TEMP_MASTER") or w.startswith("SQLITE_") or w.startswith("_CF_"):
            errs.append(f"{w.lower()} is not allowed")
    return errs


def violations(sql):
    try:
        toks = tokenize(sql)
    except SqlGuardError as e:
        return [str(e)]
    errs = []
    for n, stmt in enumerate(_split(toks), 1):
        for e in _check_statement(stmt):
            errs.append(f"statement {n}: {e}")
    return errs


def check(sql):
    """Raises SqlGuardError listing every violation; returns the sql unchanged when clean."""
    errs = violations(sql)
    if errs:
        raise SqlGuardError("SQL refused (it would touch something other than " + PREFIX + " objects): " + "; ".join(errs[:6]))
    return sql
